import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CircleGeometry } = ctx.THREE;
  const root = new Group();
  const owned = [];
  const timelines = [];
  const loadedTextures = [];

  root.userData.handlers = {};

  const makeGradientMaterial = () => {
    const material = new MeshBasicNodeMaterial();
    const gradientT = smoothstep(0.0, 1.0, uv().y);
    const bottom = vec3(0.0431, 0.0431, 0.0627); // #0b0b10
    const top = vec3(0.0863, 0.0863, 0.1137); // #16161d
    material.colorNode = mix(bottom, top, gradientT);
    return material;
  };

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    makeGradientMaterial()
  );
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  owned.push(backdrop);

  const contactShadowMaterial = new MeshBasicNodeMaterial({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });

  const contactShadow = new Mesh(
    new CircleGeometry(1.55, 48),
    contactShadowMaterial
  );
  contactShadow.scale.set(1.55, 0.32, 1);
  contactShadow.position.set(0, -0.72, -0.12);
  root.add(contactShadow);
  owned.push(contactShadow);

  const subject = new Group();
  subject.position.set(0, 0.15, 0);
  root.add(subject);

  const source = {
    x: 0,
    y: 0,
    width: 512,
    height: 320
  };

  const atlasWidth =
    config.atlasRegion?.atlasWidth ??
    config.atlas?.width ??
    config.atlasWidth ??
    source.width;

  const atlasHeight =
    config.atlasRegion?.atlasHeight ??
    config.atlas?.height ??
    config.atlasHeight ??
    source.height;

  const subjectMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2'
  });

  const subjectPlane = new Mesh(
    new PlaneGeometry(
      3.55,
      3.55 * (source.height / source.width)
    ),
    subjectMaterial
  );
  subjectPlane.position.z = 0;
  subject.add(subjectPlane);
  owned.push(subjectPlane);

  const textGroup = new Group();
  textGroup.position.set(0, 0.06, 0.16);
  subject.add(textGroup);

  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of items) {
    const text = String(item.text ?? '');
    const textObject = ctx.fontAtlas.createText(text, {
      fontSize: item.typography?.fontSize ?? 96,
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: 960
    });
    textObject.position.set(0, 0, 0);
    textGroup.add(textObject);
  }

  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38'
  });

  const accentRule = new Mesh(
    new PlaneGeometry(1.15, 0.035),
    accentMaterial
  );
  accentRule.position.set(0, -0.62, 0.18);
  subject.add(accentRule);
  owned.push(accentRule);

  const billboard = (_renderer, _scene, camera) => {
    if (camera) {
      subject.quaternion.copy(camera.quaternion);
    }
  };

  root.onBeforeRender = billboard;

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((texture) => {
        loadedTextures.push(texture);
        texture.wrapS = ctx.THREE.ClampToEdgeWrapping;
        texture.wrapT = ctx.THREE.ClampToEdgeWrapping;
        texture.repeat.set(
          source.width / atlasWidth,
          source.height / atlasHeight
        );
        texture.offset.set(
          source.x / atlasWidth,
          1 - (source.y + source.height) / atlasHeight
        );
        subjectMaterial.map = texture;
        subjectMaterial.needsUpdate = true;
      })
      .catch(() => {});
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const target = root;
    const result = ctx.primitives[primitive.name](
      target,
      primitive.params
    );
    if (result?.timeline) timelines.push(result.timeline);
    if (result?.cleanup) {
      root.userData._primitiveCleanups ??= [];
      root.userData._primitiveCleanups.push(result.cleanup);
    }
  }

  root.userData.cleanup = () => {
    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const cleanup of root.userData._primitiveCleanups ?? []) {
      cleanup?.();
    }

    for (const object of owned) {
      object.geometry?.dispose?.();
      object.material?.dispose?.();
    }

    for (const texture of loadedTextures) {
      texture.dispose?.();
    }

    root.traverse((object) => {
      if (object !== root && object.userData?.cleanup) {
        object.userData.cleanup();
      }
    });
  };

  return root;
}
